  ('rnq-2019', 'Référentiel 2019 (32 indicateurs)', 'Décret n° 2019-565 du 6 juin 2019', '2019-06-07', null, 'Applicable aux audits jusqu''au 31 octobre 2026.', 20)
insert into public.cert_criteria (referential_code, number, title) values
  ('rnq-2026', 1, 'Les conditions d''information du public sur les prestations proposées, les délais pour y accéder et les résultats obtenus'),
  ('rnq-2026', 2, 'L''identification précise des objectifs des prestations proposées et l''adaptation de ces prestations aux publics bénéficiaires lors de la conception des prestations'),
  ('rnq-2026', 3, 'L''adaptation aux publics bénéficiaires des prestations et des modalités d''accueil, d''accompagnement, de suivi et d''évaluation mises en oeuvre'),
  ('rnq-2026', 4, 'L''adéquation des moyens pédagogiques, techniques et d''encadrement aux prestations mises en oeuvre'),
  ('rnq-2026', 5, 'La qualification et le développement des connaissances et compétences des personnels chargés de mettre en oeuvre les prestations'),
  ('rnq-2026', 6, 'L''inscription et l''investissement du prestataire dans son environnement professionnel'),
  ('rnq-2026', 7, 'Le recueil et la prise en compte des appréciations et des réclamations formulées par les parties prenantes aux prestations délivrées')
