insert into public.cert_indicators (referential_code, number, criterion, short_title, text, scope, applies_when, change_kind, change_note, major_only, new_entrant_light) values
  ('rnq-2026', 1, 1, 'Information du public sur les prestations', 'Le prestataire diffuse une information accessible au public, détaillée et vérifiable sur les prestations proposées : prérequis, objectifs, type de reconnaissance de la formation délivrée, durée, modalités pédagogiques et de financements, délais d''accès, tarifs, contacts, méthodes mobilisées et modalités d''évaluation, accessibilité aux personnes en situation de handicap. Sa communication ne comporte aucune mention de nature à induire le public en erreur, notamment sur les conditions d''accès, le contenu, les modalités pédagogiques, le financement des formations, les droits ou l''absence de droits de poursuite d''études conférés par la formation préparée.', '{F,B,V,A}', 'tous', 'modifie', 'Ajout du type de reconnaissance, des modalités pédagogiques et de financement, et interdiction des mentions trompeuses.', false, false),
  ('rnq-2026', 2, 1, 'Indicateurs de résultats et méthode de calcul', 'Le prestataire diffuse des indicateurs de résultats adaptés à la nature des prestations mises en œuvre et des publics accueillis en précisant de manière transparente leurs modalités de calcul ou en s''appuyant sur des dispositifs existants.', '{F,B,V,A}', 'tous', 'modifie', 'Les modalités de calcul des résultats publiés doivent être précisées.', false, true),
  ('rnq-2026', 3, 1, 'Taux d''obtention des certifications et suites de parcours', 'Lorsque le prestataire met en œuvre des prestations conduisant à une certification professionnelle, il informe sur les taux d''obtention des certifications préparées, les possibilités de valider un/ ou des blocs de compétences, ainsi que sur les équivalences, passerelles, suites de parcours, en particulier les poursuites d''études, et les débouchés.', '{F,V,A}', 'certifiant', 'modifie', 'Ajout des poursuites d''études.', false, true),
  ('rnq-2026', 4, 2, 'Analyse du besoin', 'Le prestataire analyse le besoin du bénéficiaire en lien avec l''entreprise et/ ou le financeur concerné (s).', '{F,B,V,A}', 'tous', 'inchange', null, true, false),
  ('rnq-2026', 5, 2, 'Objectifs opérationnels et évaluables', 'Le prestataire définit les objectifs opérationnels et évaluables de la prestation.', '{F,B,V,A}', 'tous', 'inchange', null, true, false),
  ('rnq-2026', 6, 2, 'Contenus et modalités de mise en oeuvre', 'Le prestataire établit les contenus et les modalités de mise en œuvre de la prestation, adaptés aux objectifs définis et aux publics bénéficiaires.', '{F,B,V,A}', 'tous', 'inchange', null, true, false),
  ('rnq-2026', 7, 2, 'Adéquation aux exigences de la certification', 'Lorsque le prestataire met en œuvre des prestations conduisant à une certification professionnelle, il s''assure de l''adéquation du ou des contenus de la prestation aux exigences de la certification visée et peut prouver sa capacité à assurer cette certification, y compris en qualité d''organisme habilité.', '{F,A}', 'certifiant', 'modifie', 'Le prestataire doit pouvoir prouver sa capacité à assurer la certification.', true, false),
  ('rnq-2026', 8, 2, 'Positionnement et évaluation des acquis à l''entrée', 'Le prestataire détermine les procédures de positionnement et d''évaluation des acquis à l''entrée de la prestation.', '{F,A}', 'tous', 'inchange', null, false, false),
  ('rnq-2026', 9, 3, 'Information sur le déroulement de la prestation', 'Le prestataire informe les publics bénéficiaires sur les conditions de déroulement de la prestation.', '{F,B,V,A}', 'tous', 'inchange', null, false, false),
  ('rnq-2026', 10, 3, 'Adaptation, accompagnement et suivi', 'Le prestataire met en œuvre et adapte la prestation, l''accompagnement et le suivi aux publics bénéficiaires.', '{F,B,V,A}', 'tous', 'inchange', null, true, false),
  ('rnq-2026', 11, 3, 'Évaluation de l''atteinte des objectifs', 'Le prestataire évalue l''atteinte par les publics bénéficiaires des objectifs de la prestation.', '{F,B,V,A}', 'tous', 'inchange', null, true, true),
  ('rnq-2026', 12, 3, 'Engagement, ruptures et prévention des violences', 'Le prestataire décrit et met en œuvre les mesures pour favoriser l''engagement des bénéficiaires et prévenir les ruptures de parcours. Il s''assure de la prévention et du traitement de toute situation de violence, dont les violences sexistes et sexuelles, de harcèlement ou de discrimination dans le cadre de leur formation.', '{F,B,V,A}', 'tous', 'modifie', 'Ajout de la prévention et du traitement des violences, du harcèlement et des discriminations.', false, false),
  ('rnq-2026', 13, 3, 'Alternance : coordination centre et entreprise', 'Pour les formations en alternance, le prestataire, en lien avec l''entreprise, anticipe avec l''apprenant les missions confiées, à court, moyen et long terme, et assure la coordination et la progressivité des apprentissages réalisés en centre de formation et en entreprise.', '{F,A}', 'alternance', 'inchange', null, false, true),
  ('rnq-2026', 14, 3, 'Apprentissage : accompagnement socio-professionnel', 'Le prestataire met en œuvre un accompagnement socio-professionnel, éducatif et relatif à l''exercice de la citoyenneté. Il dispose d''une procédure de traitement sans délai des situations de rupture liées à des difficultés, violences ou discriminations subies par l''apprenant en formation ou dans l''entreprise d''accueil.', '{A}', 'apprentissage', 'modifie', 'Ajout d''une procédure de traitement sans délai des ruptures liées à des violences ou discriminations.', true, true),
  ('rnq-2026', 15, 3, 'Apprentissage : droits, devoirs et signalement', 'Le prestataire informe les apprentis de leurs droits et devoirs en tant qu''apprentis et salariés ainsi que des règles applicables en matière de santé et de sécurité en milieu professionnel, de manière renforcée lorsqu''ils sont mineurs. Il les informe des dispositifs d''accompagnement, de prévention et de signalement des situations de violences, de harcèlement moral ou sexuel, d''agissements sexistes et de discriminations, ainsi que des interlocuteurs susceptibles de les accompagner. Il communique les coordonnées du médiateur de l''apprentissage et veille à signaler les dysfonctionnements à l''inspection du travail.', '{A}', 'apprentissage', 'modifie', 'Information renforcée des mineurs, dispositifs de signalement, médiateur de l''apprentissage.', true, false),
  ('rnq-2026', 16, 3, 'Présentation à la certification', 'Lorsque le prestataire met en œuvre des formations conduisant à une certification professionnelle, il s''assure que les conditions de présentation des bénéficiaires à la certification respectent les exigences formelles de l''autorité de certification.', '{F,V,A}', 'certifiant', 'inchange', null, true, false),
  ('rnq-2026', 17, 4, 'Moyens humains et techniques, environnement', 'Le prestataire met à disposition ou s''assure de la mise à disposition des moyens humains et techniques adaptés et d''un environnement approprié (conditions, locaux, équipements, plateaux techniques …).', '{F,B,V,A}', 'tous', 'inchange', null, false, false),
  ('rnq-2026', 18, 4, 'Coordination des intervenants', 'Le prestataire mobilise et coordonne les différents intervenants internes et/ ou externes (pédagogiques, administratifs, logistiques, commerciaux …).', '{F,B,V,A}', 'tous', 'inchange', null, false, false),
  ('rnq-2026', 19, 4, 'Ressources pédagogiques et suivi à distance', 'Le prestataire met à disposition du bénéficiaire des ressources pédagogiques et permet à celui-ci de se les approprier. Lorsque des modules pédagogiques sont réalisés à distance, le prestataire vérifie l''effectivité de leur suivi par les apprenants. Au-delà d''un nombre d''intervenants par formation, fixé par arrêté du ministre chargé de la formation professionnelle, le prestataire dispose d''un référent pédagogique par formation chargé d''assurer la coordination pédagogique entre les intervenants.', '{F,B,V,A}', 'tous', 'modifie', 'Preuve du suivi effectif des modules à distance ; référent pédagogique au-delà d''un seuil d''intervenants fixé par arrêté (non paru au 11 octobre 2026).', false, true),
  ('rnq-2026', 20, 4, 'Apprentissage : mobilité, référent handicap, conseil de perfectionnement', 'Le prestataire dispose d''un personnel dédié à l''appui à la mobilité nationale et internationale, d''un référent handicap et d''un conseil de perfectionnement. Il s''assure de la qualité du pilotage de la formation, de la participation des apprentis, formateurs et entreprises à sa gouvernance. Lorsque la proportion d''heures d''enseignement réalisées par des intervenants permanents est inférieure à un seuil fixé par arrêté du ministre chargé de la formation professionnelle, le prestataire s''assure de la mise en œuvre de modalités renforcées de supervision pédagogique et de contrôle de la qualité des interventions.', '{A}', 'apprentissage', 'modifie', 'Pilotage et gouvernance ; supervision renforcée sous un seuil fixé par arrêté (non paru au 11 octobre 2026).', true, false),
  ('rnq-2026', 21, 5, 'Compétences des intervenants', 'Le prestataire détermine, mobilise et évalue les compétences des différents intervenants internes et/ ou externes, adaptées aux prestations.', '{F,B,V,A}', 'tous', 'inchange', null, true, false),
  ('rnq-2026', 22, 5, 'Développement des compétences des salariés', 'Le prestataire entretient et développe les compétences de ses salariés, adaptées aux prestations qu''il délivre.', '{F,B,V,A}', 'tous', 'inchange', null, true, true),
  ('rnq-2026', 23, 6, 'Veille légale et réglementaire', 'Le prestataire réalise une veille légale et réglementaire sur le champ de la formation professionnelle et en exploite les enseignements.', '{F,B,V,A}', 'tous', 'inchange', null, false, false),
  ('rnq-2026', 24, 6, 'Veille sur les compétences, métiers et emplois', 'Le prestataire réalise une veille sur les évolutions des compétences, des métiers et des emplois dans ses secteurs d''intervention et en exploite les enseignements.', '{F,B,V,A}', 'tous', 'inchange', null, false, true),
  ('rnq-2026', 25, 6, 'Veille sur les innovations pédagogiques et technologiques', 'Le prestataire réalise une veille sur les innovations pédagogiques et technologiques permettant une évolution de ses prestations et en exploite les enseignements.', '{F,B,V,A}', 'tous', 'inchange', null, false, true),
  ('rnq-2026', 26, 6, 'Accueil des publics en situation de handicap', 'Le prestataire mobilise les expertises, outils et réseaux nécessaires pour accueillir, accompagner/ former ou orienter les publics en situation de handicap.', '{F,B,V,A}', 'tous', 'inchange', null, true, true),
  ('rnq-2026', 27, 6, 'Sous-traitance et portage salarial', 'Lorsque le prestataire fait appel à la sous-traitance ou au portage salarial, il s''assure du respect de la conformité au présent référentiel et en assure la traçabilité dans les contrats de sous-traitance.', '{F,B,V,A}', 'sous_traitance', 'modifie', 'La conformité au référentiel doit être tracée dans les contrats de sous-traitance.', true, false),
  ('rnq-2026', 28, 6, 'Formation en situation de travail : réseau de partenaires', 'Lorsque les prestations dispensées au bénéficiaire comprennent des périodes de formation en situation de travail, le prestataire mobilise son réseau de partenaires socio-économiques pour co-construire l''ingénierie de formation et favoriser l''accueil en entreprise.', '{F,A}', 'fest', 'inchange', null, false, false),
  ('rnq-2026', 29, 6, 'Apprentissage : insertion professionnelle', 'Le prestataire développe des actions qui concourent à l''insertion professionnelle ou la poursuite d''étude par la voie de l''apprentissage ou par toute autre voie permettant de développer leurs connaissances et leurs compétences.', '{A}', 'apprentissage', 'inchange', null, true, false),
  ('rnq-2026', 30, 7, 'Appréciations des parties prenantes', 'Le prestataire recueille les appréciations des parties prenantes : bénéficiaires, financeurs (le cas échéant), équipes pédagogiques et entreprises concernées.', '{F,B,V,A}', 'tous', 'modifie', 'Les financeurs ne sont consultés que le cas échéant.', false, false),
  ('rnq-2026', 31, 7, 'Difficultés, réclamations et aléas', 'Le prestataire met en œuvre des modalités de traitement des difficultés rencontrées par les parties prenantes, des réclamations exprimées par ces dernières ainsi que des aléas survenus en cours de prestation.', '{F,B,V,A}', 'tous', 'modifie', 'Modification de rédaction.', true, false),
  ('rnq-2026', 32, 7, 'Amélioration continue et analyse des risques', 'Le prestataire met en place une démarche d''amélioration continue à partir de l''analyse des appréciations et des réclamations, ainsi qu''une analyse des risques sur la qualité des formations délivrées.', '{F,B,V,A}', 'tous', 'modifie', 'Ajout d''une analyse des risques sur la qualité des formations délivrées.', true, true),
  ('rnq-2026', 33, 7, 'Apprentissage : évaluation des enseignements par les apprenants', 'Le prestataire met en place un dispositif d''évaluation des contenus et des enseignements par les apprenants, distinct du recueil général de satisfaction, dont les résultats sont partagés avec les équipes pédagogiques et donnent lieu à la formalisation d''une démarche d''amélioration continue, dont il mesure périodiquement l''efficacité.', '{A}', 'apprentissage', 'nouveau', 'Nouvel indicateur, réservé aux CFA.', false, false)
