  ('rnq-2019', 18, 4, 'Coordination des intervenants', 'Le prestataire mobilise et coordonne les différents intervenants internes et/ ou externes (pédagogiques, administratifs, logistiques, commerciaux …).', '{F,B,V,A}', 'tous', null, null, false, false),
  ('rnq-2019', 19, 4, 'Ressources pédagogiques', 'Le prestataire met à disposition du bénéficiaire des ressources pédagogiques et permet à celui-ci de se les approprier.', '{F,B,V,A}', 'tous', null, null, false, true),
  ('rnq-2019', 20, 4, 'Apprentissage : mobilité, référent handicap, conseil de perfectionnement', 'Le prestataire dispose d''un personnel dédié à l''appui à la mobilité nationale et internationale, d''un référent handicap et d''un conseil de perfectionnement.', '{A}', 'apprentissage', null, null, true, false),
  ('rnq-2019', 21, 5, 'Compétences des intervenants', 'Le prestataire détermine, mobilise et évalue les compétences des différents intervenants internes et/ ou externes, adaptées aux prestations.', '{F,B,V,A}', 'tous', null, null, true, false),
  ('rnq-2019', 22, 5, 'Développement des compétences des salariés', 'Le prestataire entretient et développe les compétences de ses salariés, adaptées aux prestations qu''il délivre.', '{F,B,V,A}', 'tous', null, null, true, true),
  ('rnq-2019', 23, 6, 'Veille légale et réglementaire', 'Le prestataire réalise une veille légale et réglementaire sur le champ de la formation professionnelle et en exploite les enseignements.', '{F,B,V,A}', 'tous', null, null, false, false),
  ('rnq-2019', 24, 6, 'Veille sur les compétences, métiers et emplois', 'Le prestataire réalise une veille sur les évolutions des compétences, des métiers et des emplois dans ses secteurs d''intervention et en exploite les enseignements.', '{F,B,V,A}', 'tous', null, null, false, true),
  ('rnq-2019', 25, 6, 'Veille sur les innovations pédagogiques et technologiques', 'Le prestataire réalise une veille sur les innovations pédagogiques et technologiques permettant une évolution de ses prestations et en exploite les enseignements.', '{F,B,V,A}', 'tous', null, null, false, true),
  ('rnq-2019', 26, 6, 'Accueil des publics en situation de handicap', 'Le prestataire mobilise les expertises, outils et réseaux nécessaires pour accueillir, accompagner/ former ou orienter les publics en situation de handicap.', '{F,B,V,A}', 'tous', null, null, true, true),
  ('rnq-2019', 27, 6, 'Sous-traitance et portage salarial', 'Lorsque le prestataire fait appel à la sous-traitance ou au portage salarial, il s''assure du respect de la conformité au présent référentiel.', '{F,B,V,A}', 'sous_traitance', null, null, true, false),
  ('rnq-2019', 28, 6, 'Formation en situation de travail : réseau de partenaires', 'Lorsque les prestations dispensées au bénéficiaire comprennent des périodes de formation en situation de travail, le prestataire mobilise son réseau de partenaires socio-économiques pour co-construire l''ingénierie de formation et favoriser l''accueil en entreprise.', '{F,A}', 'fest', null, null, false, false),
  ('rnq-2019', 29, 6, 'Apprentissage : insertion professionnelle', 'Le prestataire développe des actions qui concourent à l''insertion professionnelle ou la poursuite d''étude par la voie de l''apprentissage ou par toute autre voie permettant de développer leurs connaissances et leurs compétences.', '{A}', 'apprentissage', null, null, true, false),
  ('rnq-2019', 30, 7, 'Appréciations des parties prenantes', 'Le prestataire recueille les appréciations des parties prenantes : bénéficiaires, financeurs, équipes pédagogiques et entreprises concernées.', '{F,B,V,A}', 'tous', null, null, false, false),
  ('rnq-2019', 31, 7, 'Difficultés, réclamations et aléas', 'Le prestataire met en œuvre des modalités de traitement des difficultés rencontrées par les parties prenantes, des réclamations exprimées par ces dernières, des aléas survenus en cours de prestation.', '{F,B,V,A}', 'tous', null, null, true, false),
  ('rnq-2019', 32, 7, 'Amélioration continue', 'Le prestataire met en œuvre des mesures d''amélioration à partir de l''analyse des appréciations et des réclamations.', '{F,B,V,A}', 'tous', null, null, true, true)
